<div class="page-title">P&amp;L Goals</div><p class="page-subtitle">Set targets by account, or drill down to a specific trading system.</p>
<div class="card form-card"><div class="section-heading"><div><h2 id="goal-form-title">Set goals</h2><div class="sub">Account goals apply to all trading systems. System goals apply only to trades assigned to that system.</div></div></div><form method="post" action="/goals" id="goals-form"><?=csrf_field()?><input type="hidden" name="goal_id" id="goal-id" value="0"><div class="grid"><p><label>Account</label><select name="account_id" id="goal-account" required><option value="">Select account...</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=e($a['name'].' ('.$a['currency'].')')?></option><?php endforeach;?></select></p><p><label>Trading system</label><select name="trading_system_id" id="goal-system"><option value="">Account total (all systems)</option><?php foreach($systems as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></p><p><label>Daily P&amp;L goal</label><input id="daily-goal" type="number" step="0.01" min="0" name="daily_goal" value="0" required></p><p><label>Weekly P&amp;L goal</label><input id="weekly-goal" type="number" step="0.01" min="0" name="weekly_goal" value="0" required></p><p><label>Monthly P&amp;L goal</label><input id="monthly-goal" type="number" step="0.01" min="0" name="monthly_goal" value="0" required></p><p><label>Yearly P&amp;L goal</label><input id="yearly-goal" type="number" step="0.01" min="0" name="yearly_goal" value="0" required></p></div><div class="actions"><button id="goal-save">Save goals</button><button type="button" class="secondary" id="goal-cancel" hidden>Cancel edit</button></div></form></div>
<div class="card table-wrap"><div class="section-heading"><div><h2>Current goals</h2><div class="sub">Targets are independent for each account/system combination.</div></div></div><table><thead><tr><th>Account</th><th>System</th><th>Daily</th><th>Weekly</th><th>Monthly</th><th>Yearly</th><th>Action</th></tr></thead><tbody><?php foreach($goals as $g):?><tr><td><?=e($g['account_name'])?> <span class="muted"><?=e($g['currency'])?></span></td><td><?=e($g['system_name']??'All systems')?></td><td><?=number_format((float)$g['daily_goal'],2)?></td><td><?=number_format((float)$g['weekly_goal'],2)?></td><td><?=number_format((float)$g['monthly_goal'],2)?></td><td><?=number_format((float)$g['yearly_goal'],2)?></td><td class="trade-actions"><button type="button" class="secondary goal-edit" data-id="<?=$g['id']?>" data-account="<?=$g['account_id']?>" data-system="<?=$g['trading_system_id']??''?>">Edit</button><form method="post" action="/goals" onsubmit="return confirm('Delete this P&L goal?');" style="display:inline"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="goal_id" value="<?=$g['id']?>"><button type="submit" class="danger">Delete</button></form></td></tr><?php endforeach;?><?php if(!$goals):?><tr><td colspan="7" class="muted">No P&amp;L goals configured yet.</td></tr><?php endif;?></tbody></table></div>
<script nonce="<?=e(csp_nonce())?>">(function(){const goals=<?=json_encode($goalMap,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const account=document.getElementById('goal-account'),system=document.getElementById('goal-system'),goalId=document.getElementById('goal-id'),title=document.getElementById('goal-form-title'),save=document.getElementById('goal-save'),cancel=document.getElementById('goal-cancel'),form=document.getElementById('goals-form');const set=(id,v)=>{const el=document.getElementById(id);if(el)el.value=v??0};function load(){const key=account.value+':'+(system.value||0),g=goals[key]||{daily_goal:0,weekly_goal:0,monthly_goal:0,yearly_goal:0};set('daily-goal',g.daily_goal);set('weekly-goal',g.weekly_goal);set('monthly-goal',g.monthly_goal);set('yearly-goal',g.yearly_goal)}function edit(b){account.value=b.dataset.account;system.value=b.dataset.system||'';goalId.value=b.dataset.id;const key=account.value+':'+(system.value||0),g=goals[key]||{};set('daily-goal',g.daily_goal);set('weekly-goal',g.weekly_goal);set('monthly-goal',g.monthly_goal);set('yearly-goal',g.yearly_goal);title.textContent='Edit goals';save.textContent='Update goals';cancel.hidden=false;form.scrollIntoView({behavior:'smooth',block:'start'})}function reset(){goalId.value='0';title.textContent='Set goals';save.textContent='Save goals';cancel.hidden=true;form.reset();set('daily-goal',0);set('weekly-goal',0);set('monthly-goal',0);set('yearly-goal',0)}account.addEventListener('change',()=>{if(goalId.value==='0')load()});system.addEventListener('change',()=>{if(goalId.value==='0')load()});document.querySelectorAll('.goal-edit').forEach(b=>b.addEventListener('click',()=>edit(b)));cancel.addEventListener('click',reset);})();</script>
